insert into public.maia_integrations (slug, title, description, method, url_template, body_template, auth_style, auth_header, secret_ref, risk, status, required_permission, created_by, activated_at) values
  ('whatsapp_numero_existe', 'Verificar se um número tem WhatsApp', 'Diz se um número tem WhatsApp. Parâmetro: numero (DDI + DDD + número, só dígitos).', 'POST', '{EVOLUTION_API_URL}/chat/whatsappNumbers/{EVOLUTION_INSTANCE}', '{"numbers":["{{numero}}"]}'::jsonb, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'leitura', 'active', 'integracao.usar', 'owner', now()),
  ('whatsapp_foto_perfil', 'Foto de perfil de um contato', 'Devolve o link da foto de perfil de um contato. Parâmetro: numero (DDI + DDD + número).', 'POST', '{EVOLUTION_API_URL}/chat/fetchProfilePictureUrl/{EVOLUTION_INSTANCE}', '{"number":"{{numero}}"}'::jsonb, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'leitura', 'active', 'integracao.usar', 'owner', now()),
  ('whatsapp_perfil', 'Perfil de um contato', 'Consulta nome, recado e foto de um contato. Parâmetro: numero (DDI + DDD + número).', 'POST', '{EVOLUTION_API_URL}/chat/fetchProfile/{EVOLUTION_INSTANCE}', '{"number":"{{numero}}"}'::jsonb, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'leitura', 'active', 'integracao.usar', 'owner', now()),
  ('whatsapp_perfil_comercial', 'Perfil comercial de um contato', 'Consulta o perfil comercial (descrição, categoria, site) de um contato WhatsApp Business. Parâmetro: numero.', 'POST', '{EVOLUTION_API_URL}/chat/fetchBusinessProfile/{EVOLUTION_INSTANCE}', '{"number":"{{numero}}"}'::jsonb, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'leitura', 'active', 'integracao.usar', 'owner', now()),
  ('whatsapp_etiquetas', 'Listar etiquetas', 'Lista as etiquetas da conta. Sem parâmetros.', 'GET', '{EVOLUTION_API_URL}/label/findLabels/{EVOLUTION_INSTANCE}', null, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'leitura', 'active', 'integracao.usar', 'owner', now()),
  ('whatsapp_convite_info', 'Ver um convite de grupo', 'Mostra o grupo de um convite sem entrar. Parâmetro: codigo (o código do link chat.whatsapp.com/CODIGO).', 'GET', '{EVOLUTION_API_URL}/group/inviteInfo/{EVOLUTION_INSTANCE}?inviteCode={{codigo}}', null, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'leitura', 'active', 'integracao.usar', 'owner', now()),
  ('whatsapp_privacidade', 'Ver configurações de privacidade', 'Mostra as configurações de privacidade da conta. Sem parâmetros.', 'GET', '{EVOLUTION_API_URL}/chat/fetchPrivacySettings/{EVOLUTION_INSTANCE}', null, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'leitura', 'active', 'integracao.usar', 'owner', now()),
  ('whatsapp_config_instancia', 'Ver configurações da instância', 'Mostra as configurações da instância (rejeitar ligações, sempre online, etc.). Sem parâmetros.', 'GET', '{EVOLUTION_API_URL}/settings/find/{EVOLUTION_INSTANCE}', null, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'leitura', 'active', 'integracao.usar', 'owner', now()),
  ('whatsapp_digitando', 'Mostrar ''digitando'' ou ''gravando''', 'Mostra ''digitando'' ou ''gravando áudio'' para uma conversa. Parâmetros: numero, ms (duração em milissegundos, número) e presenca (composing ou recording).', 'POST', '{EVOLUTION_API_URL}/chat/sendPresence/{EVOLUTION_INSTANCE}', '{"number":"{{numero}}","delay":"{{ms}}","presence":"{{presenca}}"}'::jsonb, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'interna', 'active', 'integracao.usar', 'owner', now()),
  ('whatsapp_arquivar_conversa', 'Arquivar ou desarquivar conversa', 'Arquiva ou desarquiva uma conversa. Parâmetros: remoteJid, id e fromMe da última mensagem dela, e arquivar (true ou false).', 'POST', '{EVOLUTION_API_URL}/chat/archiveChat/{EVOLUTION_INSTANCE}', '{"lastMessage":{"key":{"remoteJid":"{{remoteJid}}","fromMe":"{{fromMe}}","id":"{{id}}"}},"archive":"{{arquivar}}"}'::jsonb, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'interna', 'active', 'integracao.usar', 'owner', now()),
  ('whatsapp_marcar_nao_lida', 'Marcar conversa como não lida', 'Marca uma conversa como não lida. Parâmetros: remoteJid, id e fromMe da última mensagem dela.', 'POST', '{EVOLUTION_API_URL}/chat/markChatUnread/{EVOLUTION_INSTANCE}', '{"lastMessage":{"key":{"remoteJid":"{{remoteJid}}","fromMe":"{{fromMe}}","id":"{{id}}"}}}'::jsonb, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'interna', 'active', 'integracao.usar', 'owner', now()),
  ('whatsapp_etiqueta_aplicar', 'Aplicar ou tirar etiqueta', 'Aplica ou tira uma etiqueta de uma conversa. Parâmetros: numero, etiqueta_id (veja whatsapp_etiquetas) e acao (add ou remove).', 'POST', '{EVOLUTION_API_URL}/label/handleLabel/{EVOLUTION_INSTANCE}', '{"number":"{{numero}}","labelId":"{{etiqueta_id}}","action":"{{acao}}"}'::jsonb, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'interna', 'active', 'integracao.usar', 'owner', now()),
  ('whatsapp_enviar_localizacao', 'Enviar uma localização', 'Envia uma localização para um contato ou grupo. Parâmetros: numero (ou JID do grupo), nome, endereco, latitude e longitude (números).', 'POST', '{EVOLUTION_API_URL}/message/sendLocation/{EVOLUTION_INSTANCE}', '{"number":"{{numero}}","name":"{{nome}}","address":"{{endereco}}","latitude":"{{latitude}}","longitude":"{{longitude}}"}'::jsonb, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'externa', 'active', 'integracao.usar', 'owner', now()),
  ('whatsapp_enviar_contato', 'Enviar um cartão de contato', 'Envia um cartão de contato. Parâmetros: numero (destino), nome, telefone (só dígitos) e telefone_formatado (como aparece no cartão).', 'POST', '{EVOLUTION_API_URL}/message/sendContact/{EVOLUTION_INSTANCE}', '{"number":"{{numero}}","contact":[{"fullName":"{{nome}}","wuid":"{{telefone}}","phoneNumber":"{{telefone_formatado}}"}]}'::jsonb, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'externa', 'active', 'integracao.usar', 'owner', now()),
  ('whatsapp_enviar_figurinha', 'Enviar uma figurinha', 'Envia uma figurinha a partir de um link de imagem. Parâmetros: numero (ou JID do grupo) e url (https).', 'POST', '{EVOLUTION_API_URL}/message/sendSticker/{EVOLUTION_INSTANCE}', '{"number":"{{numero}}","sticker":"{{url}}"}'::jsonb, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'externa', 'active', 'integracao.usar', 'owner', now()),
  ('whatsapp_enviar_audio', 'Enviar um áudio como nota de voz', 'Envia um áudio como nota de voz a partir de um link. Parâmetros: numero (ou JID do grupo) e url (https).', 'POST', '{EVOLUTION_API_URL}/message/sendWhatsAppAudio/{EVOLUTION_INSTANCE}', '{"number":"{{numero}}","audio":"{{url}}"}'::jsonb, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'externa', 'active', 'integracao.usar', 'owner', now()),
  ('whatsapp_publicar_status', 'Publicar um status de texto', 'Publica um status de texto visível aos contatos. Parâmetros: texto, cor (hexadecimal, ex.: #008000) e fonte (número de 1 a 5).', 'POST', '{EVOLUTION_API_URL}/message/sendStatus/{EVOLUTION_INSTANCE}', '{"type":"text","content":"{{texto}}","backgroundColor":"{{cor}}","font":"{{fonte}}","allContacts":true}'::jsonb, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'externa', 'active', 'integracao.usar', 'owner', now()),
  ('whatsapp_apagar_mensagem', 'Apagar mensagem para todos', 'Apaga uma mensagem para todos. Parâmetros: id, remoteJid e fromMe (true só para mensagens enviadas pela Maia).', 'DELETE', '{EVOLUTION_API_URL}/chat/deleteMessageForEveryone/{EVOLUTION_INSTANCE}', '{"id":"{{id}}","remoteJid":"{{remoteJid}}","fromMe":"{{fromMe}}"}'::jsonb, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'externa', 'active', 'integracao.usar', 'owner', now()),
  ('whatsapp_editar_mensagem', 'Editar uma mensagem enviada', 'Edita o texto de uma mensagem que a Maia enviou. Parâmetros: numero, remoteJid, id, fromMe (true) e texto novo.', 'POST', '{EVOLUTION_API_URL}/chat/updateMessage/{EVOLUTION_INSTANCE}', '{"number":"{{numero}}","key":{"remoteJid":"{{remoteJid}}","fromMe":"{{fromMe}}","id":"{{id}}"},"text":"{{texto}}"}'::jsonb, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'externa', 'active', 'integracao.usar', 'owner', now()),
  ('whatsapp_grupo_renomear', 'Renomear um grupo', 'Muda o nome de um grupo. Parâmetros: grupo_jid (termina em @g.us) e nome.', 'POST', '{EVOLUTION_API_URL}/group/updateGroupSubject/{EVOLUTION_INSTANCE}?groupJid={{grupo_jid}}', '{"subject":"{{nome}}"}'::jsonb, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'externa', 'active', 'integracao.usar', 'owner', now()),
  ('whatsapp_grupo_descricao', 'Mudar a descrição de um grupo', 'Muda a descrição de um grupo. Parâmetros: grupo_jid e descricao.', 'POST', '{EVOLUTION_API_URL}/group/updateGroupDescription/{EVOLUTION_INSTANCE}?groupJid={{grupo_jid}}', '{"description":"{{descricao}}"}'::jsonb, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'externa', 'active', 'integracao.usar', 'owner', now()),
  ('whatsapp_grupo_revogar_convite', 'Revogar o link de convite de um grupo', 'Invalida o link de convite atual e cria outro. Parâmetro: grupo_jid.', 'POST', '{EVOLUTION_API_URL}/group/revokeInviteCode/{EVOLUTION_INSTANCE}?groupJid={{grupo_jid}}', null, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'externa', 'active', 'integracao.usar', 'owner', now()),
  ('whatsapp_grupo_config', 'Mudar quem fala ou edita no grupo', 'Define quem pode mandar mensagens ou editar o grupo. Parâmetros: grupo_jid e acao (announcement = só admins falam, not_announcement = todos falam, locked = só admins editam, unlocked = todos editam).', 'POST', '{EVOLUTION_API_URL}/group/updateSetting/{EVOLUTION_INSTANCE}?groupJid={{grupo_jid}}', '{"action":"{{acao}}"}'::jsonb, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'externa', 'active', 'integracao.usar', 'owner', now()),
  ('whatsapp_grupo_temporarias', 'Mensagens temporárias no grupo', 'Liga ou desliga mensagens temporárias. Parâmetros: grupo_jid e segundos (0 desliga, 86400 = 24 h, 604800 = 7 dias, 7776000 = 90 dias; número).', 'POST', '{EVOLUTION_API_URL}/group/toggleEphemeral/{EVOLUTION_INSTANCE}?groupJid={{grupo_jid}}', '{"expiration":"{{segundos}}"}'::jsonb, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'externa', 'active', 'integracao.usar', 'owner', now()),
  ('whatsapp_grupo_entrar_por_convite', 'Entrar em um grupo por convite', 'A conta da Maia entra em um grupo pelo código do convite. Parâmetro: codigo.', 'GET', '{EVOLUTION_API_URL}/group/acceptInviteCode/{EVOLUTION_INSTANCE}?inviteCode={{codigo}}', null, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'externa', 'active', 'integracao.usar', 'owner', now()),
  ('whatsapp_sair_do_grupo', 'Sair de um grupo', 'A conta da Maia sai do grupo. Parâmetro: grupo_jid.', 'DELETE', '{EVOLUTION_API_URL}/group/leaveGroup/{EVOLUTION_INSTANCE}?groupJid={{grupo_jid}}', null, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'externa', 'paused', 'integracao.usar', 'owner', null),
  ('whatsapp_bloquear_contato', 'Bloquear ou desbloquear um contato', 'Bloqueia ou desbloqueia um contato. Parâmetros: numero e acao (block ou unblock).', 'POST', '{EVOLUTION_API_URL}/chat/updateBlockStatus/{EVOLUTION_INSTANCE}', '{"number":"{{numero}}","status":"{{acao}}"}'::jsonb, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'externa', 'paused', 'integracao.usar', 'owner', null),
  ('whatsapp_perfil_nome', 'Mudar o nome do perfil da Maia', 'Muda o nome de perfil da conta. Parâmetro: nome.', 'POST', '{EVOLUTION_API_URL}/chat/updateProfileName/{EVOLUTION_INSTANCE}', '{"name":"{{nome}}"}'::jsonb, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'externa', 'paused', 'integracao.usar', 'owner', null),
  ('whatsapp_perfil_recado', 'Mudar o recado do perfil da Maia', 'Muda o recado (bio) do perfil da conta. Parâmetro: recado.', 'POST', '{EVOLUTION_API_URL}/chat/updateProfileStatus/{EVOLUTION_INSTANCE}', '{"status":"{{recado}}"}'::jsonb, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'externa', 'paused', 'integracao.usar', 'owner', null),
  ('whatsapp_perfil_remover_foto', 'Remover a foto do perfil da Maia', 'Remove a foto de perfil da conta. Sem parâmetros.', 'DELETE', '{EVOLUTION_API_URL}/chat/removeProfilePicture/{EVOLUTION_INSTANCE}', null, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'externa', 'paused', 'integracao.usar', 'owner', null),
  ('whatsapp_privacidade_alterar', 'Alterar as configurações de privacidade', 'Altera a privacidade da conta. Parâmetros (todos obrigatórios): confirmacao_leitura (all ou none), foto, status, visto_por_ultimo e adicionar_em_grupos (all, contacts, contact_blacklist ou none) e online (all ou match_last_seen). Consulte antes com whatsapp_privacidade.', 'POST', '{EVOLUTION_API_URL}/chat/updatePrivacySettings/{EVOLUTION_INSTANCE}', '{"readreceipts":"{{confirmacao_leitura}}","profile":"{{foto}}","status":"{{status}}","online":"{{online}}","last":"{{visto_por_ultimo}}","groupadd":"{{adicionar_em_grupos}}"}'::jsonb, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'externa', 'paused', 'integracao.usar', 'owner', null),
  ('whatsapp_reiniciar_instancia', 'Reiniciar a conexão da Maia', 'Reinicia a instância do WhatsApp da Maia. Ela fica fora do ar por instantes. Sem parâmetros.', 'POST', '{EVOLUTION_API_URL}/instance/restart/{EVOLUTION_INSTANCE}', null, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'externa', 'paused', 'integracao.usar', 'owner', null),
  ('whatsapp_desconectar_instancia', 'Desconectar o WhatsApp da Maia', 'ATENÇÃO: desconecta o WhatsApp da Maia. Só volta lendo o QR code de novo no aparelho. Sem parâmetros.', 'DELETE', '{EVOLUTION_API_URL}/instance/logout/{EVOLUTION_INSTANCE}', null, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'externa', 'paused', 'integracao.usar', 'owner', null),
  ('whatsapp_apagar_instancia', 'Apagar a instância da Maia', 'ATENÇÃO: apaga a instância da Maia na Evolution, com o webhook e as configurações. Só use se o dono pedir de forma explícita. Sem parâmetros.', 'DELETE', '{EVOLUTION_API_URL}/instance/delete/{EVOLUTION_INSTANCE}', null, 'apikey_header', 'apikey', 'EVOLUTION_API_KEY', 'externa', 'paused', 'integracao.usar', 'owner', null)
